window.FILM_WORK_PROMPTS={"work_id":"src-a0df77bfa11ca241","records":[{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-03567036f8b3d616","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers007.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"空旷的沥青停车场内，一名站立男子与一名坐于圆柱基座上的男子相对，背景为远处的树林与灰白天空。","analysis":"画面采用平视视角，构图开阔，大面积的灰色地面占据前景与中景，黄色停车线呈对角线分布。两名人物位于画面中心偏左，左侧男子全身站立，右侧男子全身坐于深色立柱下的圆形基座上。光线为均匀的漫射自然光，无强烈阴影，色彩饱和度低，整体呈现灰绿与灰蓝的冷色调，远景树木轮廓模糊。","prompt":"低分辨率画面，展示一个空旷的户外沥青停车场。地面呈灰色，绘有模糊的黄色停车标线。画面中央偏左，一名身穿蓝色长袖衬衫、黑色长裤和白色鞋子的男子站立，面向右侧。在他对面，一名身穿紫色上衣、浅色长裤和白色鞋子的男子坐在深色立柱底部的圆形混凝土基座上。背景是一排深绿色的树林，上方是灰白色的天空。光线平淡均匀，无强烈对比，整体色调偏冷且饱和度低，呈现出一种静止、空旷的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:05-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers007.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-e0dde42033e23919","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-bc2b47ce5e07486f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers020.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"昏暗室内，暖黄灯光照亮中央区域。一人坐于带轮躺椅中，另一人站立于右侧，背景可见窗户与墙壁，前景有模糊栏杆遮挡。","analysis":"画面呈框式构图，前景黑色栏杆形成遮挡。左侧人物坐于躺椅，全身轮廓可见但细节模糊；右侧人物站立，身形较小。室内暖黄光与外部黑暗形成强烈对比，光源来自左上方，营造出封闭、压抑的视觉氛围。","prompt":"低分辨率昏暗室内场景，暖黄色灯光从左侧窗户射入，照亮房间中央。一名人物坐在一把带轮子的躺椅中，身体后仰，轮廓模糊。右侧站立着另一名人物，身形较小，面向坐者。背景是带有窗框的墙壁，光线在墙面形成光晕。前景有黑色的金属栏杆或框架结构，部分遮挡视线，增加了画面的层次感。整体色调偏黄褐，对比度强烈，呈现出一种老旧、压抑的视觉质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:11-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers020.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-3c172d9017905279","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-54bc7dd00c3fc703","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers033.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"画面主体为一名头部覆盖大面积红色物质的人物，身穿粉色花纹上衣，位于室内厨房环境中，背景可见白色橱柜与台面。","analysis":"构图采用正面平视角度，人物头部及肩部占据画面中心主要位置，背景环境约占画面三分之一。光线均匀柔和，无明显阴影，色彩以人物头部的鲜红色与衣物的粉色为主，与背景冷白色的橱柜形成对比。","prompt":"低分辨率室内画面，一名人物位于画面中央，头部及面部覆盖着大面积不规则的红色粘稠物质，呈现出粗糙的纹理质感。人物身穿粉色带有花纹的翻领上衣，仅可见头部与肩颈部位。背景为厨房环境，可见白色的橱柜门板、把手以及米黄色的台面，台面左上方有模糊的金属水槽轮廓。整体光线平淡，色彩饱和度一般，画面具有明显的颗粒感与模糊感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:16-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers033.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-0206157630170b99","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-7d945af90eafa057","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers046.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"一名戴浅色头巾、穿红色短袖的人物坐在草地上的树桩上，身体侧向画面右侧，头部仰起。背景是开阔的绿色草坪和远处的房屋建筑。","analysis":"画面主体位于右侧三分之一处，人物呈坐姿，全身可见，头部仰起。人物占据画面约三分之一高度，背景草坪占据大部分空间，远处有模糊的房屋轮廓。光线为自然散射光，整体色调偏绿，人物红色上衣在绿色背景中形成对比。画面清晰度较低，细节模糊，色彩饱和度一般。","prompt":"低分辨率画面，一名戴浅色头巾、穿红色短袖上衣和深色长裤的人物坐在草地上的树桩上，身体侧向右侧，头部仰起。人物位于画面右侧，占据约三分之一高度。背景是大片绿色草坪，远处有模糊的房屋建筑轮廓和树木。自然光照明，整体色调偏绿，红色上衣与绿色背景形成对比。画面清晰度低，细节模糊，色彩饱和度一般。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:21-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers046.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-9d9d9baecacd6b0b","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-946b931280b47f8b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers059.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"夜间户外场景，左侧为带有一排窗户的浅色建筑墙体，中央立有被强光照亮的白色方形标志牌，右侧远处可见模糊的人影轮廓，前景为暗色路面。","analysis":"画面采用横向构图，左侧大面积墙体占据约三分之一画面，中央标志牌作为视觉焦点，被强白光垂直照亮，形成高对比度。右侧背景较暗，仅能辨识出模糊的人形轮廓和类似长椅的结构。前景路面呈现暗红色调，整体光线昏暗，仅标志牌区域明亮，其余部分处于阴影中，色彩层次以黑、白、暗红为主。","prompt":"夜间低分辨率户外画面，左侧是一堵延伸的浅色建筑外墙，上方有一排矩形窗户。画面中央竖立着一个被强光照亮的白色方形标志牌，顶部有十字形结构，标志牌后方有一棵深绿色树木。右侧背景昏暗，隐约可见一个站立的人影轮廓和类似长椅的物体。前景是模糊的暗红色路面，整体画面噪点明显，光线集中在标志牌区域，周围环境处于黑暗中，呈现出夜间监控或低光摄影的质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T03:16:28-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers059.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-d29d9fc51b460dce","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-ecbd1fa6c267a45d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers008.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"夜间户外，一根高耸的灯杆立于画面中央，顶端亮着几盏强光灯，背景为漆黑夜空，左下角有一团模糊的亮区。","analysis":"画面采用中心构图，垂直灯杆贯穿画面，将视觉重心引向顶部的光源。环境占比极大，背景几乎全黑，仅见灯杆轮廓与顶部灯光。明暗对比强烈，顶部灯光呈粉白色，左下角亮区呈暖白色，整体色调单一，以黑、白、灰为主，无可见人物或复杂物体。","prompt":"夜间户外场景，画面中央竖立一根细长的金属灯杆，顶端横向排列着几盏明亮的强光灯，灯光在黑暗中形成粉白色的光晕。背景是漆黑的夜空，没有任何其他景物。画面左下角有一团模糊的暖白色亮区，可能是地面反光或另一处光源。整体画面颗粒感强，分辨率较低，明暗对比极高，呈现出一种空旷、寂静的夜间氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T22:07:01+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers008.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-ced043b996124c8a","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-c4bf2ede1e6673ac","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers021.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"一名光头男子身穿绿色上衣，坐在户外深色躺椅上。他双手持握一根极长的浅棕色管状物，将其一端抵在嘴边，管身向右上方斜向延伸。背景为灰褐色横向木板墙，左侧可见门框边缘。","analysis":"画面呈现低分辨率的录像质感，色彩略显陈旧。人物位于画面左侧，占据约三分之一的宽度，呈坐姿，仅可见上半身及部分大腿。那根长管状物是视觉重心，从人物面部延伸至画面右上角，形成强烈的对角线构图。光线为自然散射光，无强烈阴影，整体色调偏暖黄与灰褐。","prompt":"一段低分辨率的复古录像画面，画质模糊且带有噪点。画面主体是一名光头男子，身穿绿色短袖上衣，坐在户外的深蓝色躺椅上。他双手握着一根极长的浅棕色圆管，管身向右上方倾斜，几乎贯穿整个画面对角线，管口靠近他的嘴部。背景是灰褐色的横向木板墙壁，左侧边缘可见模糊的门框结构。光线平淡，色彩饱和度低，呈现出一种陈旧、随意的生活记录氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T22:07:07+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers021.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-d8080537fb12d738","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-a5f71fda069a937e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers034.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"一名金发白须人物仰躺在米黄色带黑点的地面上，身穿黑色荷叶边上衣。人物左侧地面有大片深褐色液体状色块，左上方可见模糊的灰褐色物体轮廓。","analysis":"画面采用高角度俯视构图，人物位于画面右侧，头部朝上，身体向下方延伸，仅上半身及肩部清晰可见。左侧深褐色色块占据约三分之一画面，与米黄色背景形成强烈对比。光线均匀偏暖，整体色调泛黄，画质模糊，无明显的明暗阴影层次，呈现出一种平面化的视觉效果。","prompt":"低分辨率俯视画面，米黄色带黑色小方点的地面背景。一名金发白须人物仰躺，身穿黑色短袖荷叶边上衣，领口和袖口有白色装饰。人物位于画面右侧，头部朝上，面部朝上。人物左侧地面有大片深褐色不规则液体状色块，延伸至画面左下边缘。左上方有模糊的灰褐色物体轮廓。整体色调偏黄，光线均匀，画质模糊，无清晰阴影。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T22:07:13+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers034.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-66c77eda715d0a9e","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-ab6c3e00558913ce","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers047.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"户外林间空地，一名穿红衣戴帽的人物站在粉色自行车旁，双手扶树。背景处有两名人物及两辆自行车，地面铺满落叶，左侧为绿色草地。","analysis":"画面采用平视视角，前景人物占据右侧主要空间，全身可见，身形较大。背景人物位于中景偏左，身形较小，呈站立或倚靠姿态。光线为自然散射光，整体色调偏暗，绿色植被与褐色树干形成对比，粉色自行车在暗色背景中较为显眼。","prompt":"低分辨率户外画面，右侧前景一名穿红色短袖、戴浅色帽子的人物全身可见，正站在粉色山地自行车旁，双手扶着一棵粗壮的褐色树干。背景左侧中景处有两名站立的人物，旁边停放着两辆深色自行车。地面覆盖着褐色落叶，左侧延伸出一片绿色草地，远处可见模糊的树木与房屋轮廓。自然光照明，色彩饱和度较低，呈现出一种陈旧、模糊的视觉质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T22:07:18+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers047.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-906535eb7398cdac","origin":"visual"},{"work_id":"src-a0df77bfa11ca241","frame_id":"FG-ba0e1b84afdd0615","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers060.jpg","source_page":"https://film-grab.com/2017/02/14/trash-humpers/","scene":"夜间户外，一座低矮的长方形建筑位于画面中央，内部透出暖黄光。建筑右侧远处有一盏路灯，前景为黑暗的地面，整体环境空旷且昏暗。","analysis":"画面采用中心构图，主体建筑占据画面中部约三分之一宽度。由于分辨率低，建筑细节模糊，仅能辨识出左侧的窗户轮廓和右侧明亮的门洞区域。光源主要来自建筑内部，形成强烈的明暗对比，将前景地面照亮一小片。右上角的路灯形成独立的橙色光点，与主体光源形成呼应。整体色调偏暗，以黑色背景衬托暖色光区。","prompt":"低分辨率夜间监控风格画面，画质粗糙且噪点明显。画面中央是一座单层长方形简易建筑，墙体呈灰褐色，左侧有一个暗色矩形窗户，右侧是一个透出强烈暖黄光的门洞，光线在门前地面形成光晕。建筑周围是大面积漆黑的空地，前景为模糊的暗色地面。画面右上角远处有一盏路灯，发出橙红色的光，在黑暗中形成光斑。整体氛围压抑、寂静，明暗对比强烈，仅靠建筑内部灯光和远处路灯照亮局部，其余部分完全隐没在夜色中。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T22:07:25+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/trashhumpers060.jpg","observed_dimensions":[500,281],"source_thumbnail_dimensions":[500,281],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-e73f391205c299fe","origin":"visual"}]};